#### Iteration 3: Loop Unrolling
```python
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define UNROLL_FACTOR 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int n) {
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int bx = blockIdx.x, by = blockIdx.y;
    int tx = threadIdx.x, ty = threadIdx.y;

    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    float sum = 0.0f;

    for (int p = 0; p < (n + TILE_SIZE - 1) / TILE_SIZE; p++) {
        int A_col = p * TILE_SIZE + tx;
        int B_row = p * TILE_SIZE + ty;

        if (row < n && A_col < n) {
            As[ty][tx] = A[row * n + A_col];
        } else {
            As[ty][tx] = 0.0f;
        }

        if (B_row < n && col < n) {
            Bs[ty][tx] = B[B_row * n + col];
        } else {
            Bs[ty][tx] = 0.0f;
        }

        __syncthreads();

        #pragma unroll UNROLL_FACTOR
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += As[ty][k] * Bs[k][tx];
        }
        __syncthreads();
    }

    if (row < n && col < n) {
        C[row * n + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    int n = A.size(0);
    auto C = torch::zeros({n, n}, A.options());

    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((n + block.x - 1) / block.x, (n + block.y - 1) / block.y);

    matmul_kernel<<<grid, block>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), n);

    return C;
}
"""

cpp_source = "torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B);"

matmul_extension = load_inline(
    name='matmul_extension',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['matmul_cuda'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()

    def forward(self, a, b):
        return matmul_extension.matmul_cuda(a, b)
```

### Explanation
1. **Iteration 1**: The basic kernel assigns each thread to compute one element of the output matrix. Each thread accesses global memory for every element in the corresponding row and column, leading to high latency.
2. **Iteration 2**: Shared memory is used to cache tiles of the input matrices. Threads within a block collaborate to load data into shared memory, reducing global memory accesses and improving data reuse.
3. **Iteration 3**: Loop unrolling is applied to the inner loop, reducing loop overhead and enabling better instruction-level parallelism. The `#pragma unroll` directive hints the compiler to unroll the loop, which can improve performance by reducing branch instructions and increasing pipeline efficiency.

Each iteration builds upon the previous one, focusing on different optimization techniques to enhance performance while maintaining correctness. The evaluations after each iteration ensure that the optimizations do not introduce errors and provide measurable performance improvements.
